//! Build a throwaway session, use it, and leave nothing behind.
//!
//! ```console
//! $ cargo run --example scratch
//! ```

use std::time::Duration;

use libtmux::test::unique_name;
use libtmux::{NewWindowOptions, PaneWait, Server, SplitDirection, SplitOptions};

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // An example must not build sessions on whatever server the reader
    // happens to be using, so this one gets a socket of its own. More than one
    // libtmux runs on a developer's machine, so it goes in a directory this
    // one owns rather than straight into the temporary directory.
    let root = std::path::Path::new("/tmp/libtmux-rs-dev");
    std::fs::create_dir_all(root)?;
    let socket = root.join(format!("{}.sock", unique_name("libtmux-scratch")));
    let server = Server::builder().socket_path(&socket).build()?;

    // The scope kills the session whether the body succeeds or fails, so a
    // failure partway through does not leave a session behind.
    println!("server on {}", socket.display());

    let output = server
        .with_session(unique_name("scratch").as_str(), async |session| {
            println!("  session {} created", session.id());

            let window = session
                .new_window(NewWindowOptions::new("work").command("sh"))
                .await?;
            println!("  window {} running sh", window.id());

            window
                .split(SplitOptions::new(SplitDirection::Below).command("sh"))
                .await?;
            println!("  split it: {} panes", window.panes().await?.len());

            // A window always has an active pane, but saying so with a panic
            // would be a worse example than handling it.
            let Some(pane) = window.active_pane().await? else {
                return Ok(0);
            };
            println!("  typing into {}", pane.id());
            pane.send_line("printf 'hello from tmux\\n'").await?;

            // tmux runs the shell asynchronously, so wait for the output
            // rather than sleeping and hoping. The outcome is checked because
            // a wait that reached its deadline still returns successfully.
            match pane.wait_for_text("hello", Duration::from_secs(5)).await? {
                PaneWait::Arrived => println!("  the pane printed it"),
                other => println!("  gave up: {other:?}"),
            }

            // region: capture
            let lines = pane.capture().await?;
            for line in lines.iter().filter(|line| !line.as_bytes().is_empty()) {
                println!("  | {}", line.to_string_lossy());
            }
            // endregion

            Ok::<_, Box<dyn std::error::Error>>(lines.len())
        })
        .await?;

    println!("captured {output} lines, then the scope killed the session");

    // The lenient form is the one that answers this question. The scope killed
    // the only session, so tmux exited with it, and the loud form reports that
    // as the failure it is rather than as the empty listing this is asking for.
    assert!(
        server.sessions().await.unwrap_or_default().is_empty(),
        "the scope cleaned up",
    );

    println!(
        "sessions left behind: {}",
        server.sessions().await.unwrap_or_default().len()
    );

    server.shutdown().await?;

    // tmux does not unlink its socket when the server exits, so whatever named
    // one owns removing it. Leaving it behind is invisible until /tmp fills up.
    std::fs::remove_file(&socket)?;
    Ok(())
}

rs/mcp:crates/tmux-mcp/examples/readonly.content:
//! Serve tmux over MCP, offering only the inspect toolset.
//!
//! The shipped binary reads `LIBTMUX_TOOLSETS` at startup. Building the server
//! yourself is how you decide it in code instead, which is
//! what you want when the surface is a property of the program rather than of
//! how someone launched it.
//!
//! ```console
//! $ cargo run --example readonly
//! ```
//!
//! Then talk MCP to it on stdin and stdout.

use libtmux::Server;
use rmcp::ServiceExt as _;
use rmcp::transport::stdio;
use tmux_mcp::{Selection, TmuxTools};

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let tools = TmuxTools::builder(Server::new()?)
        .selection(Selection::parse(Some("inspect"), None, None)?)
        .build();

    // stdout carries the protocol, so this goes to stderr.
    eprintln!("serving {} inspect tools", tools.offered().len());

    tools.serve(stdio()).await?.waiting().await?;
    Ok(())
}

rs/workspace:crates/tmux-workspace/examp.content:
//! Read a workspace, see what it would do, build it, and read it back.
//!
//! The command does all of this for a file; a program does it with the
//! library when the workspace is data it made itself. Everything runs against
//! an isolated tmux under `/tmp/libtmux-rs-test/`, removed at the end.
//!
//! ```console
//! $ cargo run --example build
//! ```

use libtmux::test::TestServer;
use tmux_workspace::{Workspace, WorkspaceBuilder, freeze};

const WORKSPACE: &str = "
session_name: api
windows:
  - window_name: editor
    layout: even-horizontal
    panes:
      - echo editing
      - echo tests
  - window_name: logs
    panes:
      - echo tailing
";

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let workspace = Workspace::from_yaml(WORKSPACE)?;
    let guard = TestServer::new().await?;
    let builder = WorkspaceBuilder::new(guard.server());

    // Every step the build will take, before any of them runs. A step whose
    // target is created by an earlier one has no id to show until then.
    let plan = builder.plan(&workspace);
    println!("{} steps", plan.len());
    for (step, rendered) in plan.steps().iter().zip(plan.preview()) {
        match rendered {
            Some(command) => println!("  {}", command.summary()),
            None => println!(
                "  {} on an object an earlier step creates",
                step.kind().name()
            ),
        }
    }

    let session = builder.build(&workspace).await?;
    for window in session.windows().await? {
        let panes = window.panes().await?.len();
        let noun = if panes == 1 { "pane" } else { "panes" };
        println!("built {}: {panes} {noun}", window.name().to_string_lossy());
    }

    // What is running now, as a workspace again: the shape, not the history.
    println!("{}", freeze(&session).await?.to_yaml());

    guard.shutdown().await?;
    Ok(())
}

